insert into public.cpl_memory (slug, kind, org, title, summary, detail, plain, tags, affects, source, related, author, event_date, status, verified_by)
values
('sam-ask-sierra-chip-sidebar-2026-10-24', 'decision', 'cpl', 'Sam asks for an Ask Sierra chip that opens a Sierra side bar when clicked; next session builds it', 'Sam, 2026-10-24 ~17:10Z, mid-session in S468: "Can you add an Ask Sierra chat chip that opens a Sierra side bar if clicked?" Then, a minute later: "We can do that next session:)"', 'He sent it while S468 worked on the public CPL Library and the funding asks, and named no page. The page in hand was the public library (library/index.html, Malone''s look). Existing Ask Sierra links open sierra/ in a new tab (index.html, funding-model/index.html, cpl_pathways.js); none opens a side bar. The next session confirms the page or pages in one line, then builds the chip and the side bar.', 'Sam wants an Ask Sierra button that opens Sierra in a panel beside the page instead of a new tab.', array['sierra','library','public-library','ui','sam-ask']::text[], array['library/index.html','sierra/index.html']::text[], 'Sam in chat, S468, 2026-10-24 ~17:10Z', array['sam-public-library-malone-look-2026-10-24']::text[], 'SkyMatilija-S468', '2026-10-24', 'verified', 'Sam (his ask in chat, 2026-10-24)'),
('public-library-toolkit-photos-built-2026-10-24', 'milestone', 'cpl', 'The public library''s hero cycles through Sam''s ten Career Education toolkit photos after Malone''s student (cpl-project-tracker#2421)', 'Built and merged by S468 on 2026-10-24 under Sam''s Sheet 124 card 1 (attach): ten JPEGs from his Drive folder Photos, each cropped to 4:3 around its people at most 1,200 px wide, the student recropped to 4:3, one object-position 50% 50%, only the first slide loaded up front. Baking and Nursing exist only as zips over the Drive connector''s 10 MB limit.', 'tests/public_library.test.js (6e) fails a slide whose file is missing, is not 4:3 or misstates its size. A cycling page''s setInterval kept every jsdom window alive and the test ran to its timeout after 108/108; windows that do not test the cycle now load the page stripped to its first slide.', 'The public library''s banner now rotates through eleven photos of students in career programs.', array['library','public-library','photos','tests']::text[], array['library/index.html','library/photos/','tests/public_library.test.js']::text[], 'cpl-project-tracker#2421, merged 2026-10-24', array['sam-sheet-124-rulings-2026-10-24','public-library-malone-look-built-2026-10-24']::text[], 'SkyMatilija-S468', '2026-10-24', 'proposed', null),
('nc-outcome-cards-edit-like-credit-cards-2026-10-24', 'milestone', 'cpl', 'The noncredit outcome cards edit as the credit cards do, with the measure, target rule, outcomes served and strategies (cpl-project-tracker#2422)', 'S468, Sam''s ask of 2026-10-24 13:38Z ("I need to be able to edit the new NC priority boxes"): the NC cards were read-only without a reviewer sign-in (ro = publicMode() || !unlocked()) while the credit cards edit for anyone, so his screenshot showed no fields.', 'They now follow the credit cards (signed in for the team, signed out a what-if) and carry the measure (noncredit outcome sources alone), the target rule (kind, floor, percent, cap), the Serves boxes and the strategies. tests/cpl_funding_nc_outcomes.test.js E0 to E8; four mutations caught. setNcOutcome replaces the year''s whole list in the active layer, so a test fixture handed to _setShared must be cloned. parseNum strips non-digits, so free text parses as 0; the rule fields require a digit.', 'Sam can now change every part of the two noncredit outcome cards on the funding tab.', array['implementation-funding','noncredit','cards','ui']::text[], array['cpl_funding.js','tests/cpl_funding_nc_outcomes.test.js']::text[], 'cpl-project-tracker#2422', array['sam-nc-cards-cabrillo-map-roles-2026-10-24']::text[], 'SkyMatilija-S468', '2026-10-24', 'proposed', null),
('nc1-mirror-channel-countable-cabrillo-2026-10-24', 'fact', 'cpl', 'NC-1 counts from data on its mirror channel: 33 Cabrillo exhibits target a credit course with a CDCP twin, against a target of 9; 4 of 102 colleges meet on it', 'S468 dry run, 2026-10-24 (funding/nc_outcome_feasibility/2026-10-24_cabrillo/): an exhibit counts when one of its sample target credit courses (chatbox_exhibits.sample_courses) has a CDCP noncredit course with the same title_norm at the college. Cabrillo: 33 of 79 exhibits, target 9 (166 CDCP courses); it numbers its noncredit twins 400 above the credit course.', 'Statewide: 4 of 102 colleges with CDCP courses meet their target on this channel alone, 8 have some, 90 none; 38 of 410 target exhibits counted. NC-2 is confirmable in COCI by a named control number and not findable by title (two Cabrillo portfolio courses are professional portfolios; one noncredit title statewide names prior learning). Channel 1 adds nothing at Cabrillo (no MAP exhibit targets a noncredit course); channel 3 needs a curated credential-to-course match (CompTIA A+, EMT); channel 4 is attested by definition. sample_courses may list fewer than all target courses, so the count is a floor.', 'A college''s noncredit exhibits can be counted from MAP and the course catalog, without asking the college to attest, for the first noncredit outcome.', array['implementation-funding','noncredit','nc-outcomes','cabrillo','measured']::text[], array['funding/nc_outcome_feasibility/2026-10-24_cabrillo/README.md','funding/nc_outcome_feasibility/2026-10-24_cabrillo/nc1_mirror_channel.sql']::text[], 'Supabase MCP reads, S468, 2026-10-24 ~17:35Z', array['sam-nc-cards-cabrillo-map-roles-2026-10-24','sam-sheet-114-rulings-2026-10-22']::text[], 'SkyMatilija-S468', '2026-10-24', 'proposed', null),
('map-cpl-coordinator-source-college-contacts-2026-10-24', 'fact', 'cpl', 'The funding coordinator condition, the landing page and Sierra''s contact cascade all read the CPL Coordinator fields of MAP''s College Contacts', 'S468, 2026-10-24: map/sync_map_users.py maps "CPL Coordinator" and "CPL Coordinator Email" from View_CollegeContacts_APIDataset into map_college_contacts daily; map_coordinator_summary() returns the boolean the funding condition and the MAP Users tab read. 56 of 124 colleges carry one (synced 16:19Z).', 'The noncredit coordinator condition reads coordinator_name on COBI''s attestation row (ncCondList, cpl_funding_nc_attestation_pub) and swaps one for one to a has_nc_cpl_lead boolean once MAP carries the role. So a MAP CPL Coordinator role needs only to feed the College Contacts field. Which MAP users may edit College Contacts is MAP''s to say; COBI''s data does not show it. Open Asks Sheet 125 card 2 carries the drafted request to Pedro and the CSM team.', 'The CPL coordinator every surface shows comes from one field each college fills in MAP.', array['map-users','implementation-funding','coordinator','map-roles']::text[], array['map/sync_map_users.py','map/supabase_map_contacts.sql','cpl_funding.js']::text[], 'S468 code read and a map_college_contacts read, 2026-10-24', array['sam-nc-cards-cabrillo-map-roles-2026-10-24']::text[], 'SkyMatilija-S468', '2026-10-24', 'proposed', null),
('pitfall-exhibits-without-id-drop-from-distinct-counts-2026-10-24', 'pitfall', 'cpl', '61 MAP exhibits carry no exhibit_id, so a count(distinct exhibit_id) drops them; key by id or title', 'S468, 2026-10-24: chatbox_exhibits holds 61 rows statewide with exhibit_id null (4 at Cabrillo). The first Cabrillo mirror count read 29 by id and 33 by title; count(distinct coalesce(exhibit_id::text, ''t:''||exhibit_title)) counts all of them.', 'Any builder that counts exhibits (the NC-1 builder, adoption counts) must key them this way or under-count silently.', 'Some exhibits have no ID number, so counting by ID alone misses them.', array['exhibits','map','pitfall','counts']::text[], array['funding/nc_outcome_feasibility/2026-10-24_cabrillo/nc1_mirror_channel.sql']::text[], 'Supabase MCP read, S468, 2026-10-24', array['nc1-mirror-channel-countable-cabrillo-2026-10-24']::text[], 'SkyMatilija-S468', '2026-10-24', 'proposed', null)
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
